# S7_make_predictions.R -- generated by JSDMWorkbench
library(Hmsc)
modelDir <- file.path('.', 'models'); resultDir <- file.path('.', 'results'); predDir <- file.path('.', 'predictions')
samples <- 2
thin <- 1
nChains <- 1
load(file.path(modelDir, paste0('models_thin_', thin, '_samples_', samples, '_chains_', nChains, '.Rdata')))
pdf(file.path(resultDir, 'predictions.pdf'))
for (j in seq_along(models)) {
  m <- models[[j]]
  covariates <- intersect(all.vars(m$XFormula), colnames(m$XData))
  if (length(covariates) == 0) covariates <- colnames(m$XData)
  for (covariate in covariates) {
    Gradient <- tryCatch(constructGradient(m, focalVariable = covariate), error=function(e) NULL)
    if (!is.null(Gradient)) { predY <- tryCatch(predict(m, Gradient=Gradient, expected=TRUE), error=function(e) NULL); if (!is.null(predY)) { saveRDS(predY, file.path(predDir, paste0('gradient_prediction_', names(models)[j], '_', covariate, '.rds'))); try(plotGradient(m, Gradient, pred=predY, yshow=0, measure='S', showData=TRUE, main=paste0(names(models)[j], ': ', covariate)), silent=TRUE) } }
  }
}
dev.off()
